ndif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-30T07:41:12.933Z', '2026-10-30T07:41:14.846Z', 'Order shipped', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
